function [vr] = corotating_velocity(r, v, w)
%COROTATING_VELOCITY  The velocity relative to air that turns with the Earth at rate w about the z axis: v - w x r.
%   r: real[m][3] (passed in m)
%   v: real[m/s][3] (passed in m/s)
%   w: real[1/s] (passed in 1/s)
%   returns vr: real[m/s][3] (passed in m/s)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    vr = zeros(3, 1);
    vr = [(v(1) + (w * r(2))); (v(2) - (w * r(1))); v(3)];
end
